import{_ as t,o,c as a,ag as n}from"./chunks/framework.em2JOrjF.js";const u=JSON.parse('{"title":"Allocations & Envelopes","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/allocations.md","filePath":"concepts/allocations.md"}'),s={name:"concepts/allocations.md"};function r(l,e,i,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="allocations" tabindex="-1">Allocations &amp; Envelopes <a class="header-anchor" href="#allocations" aria-label="Permalink to &quot;Allocations &amp; Envelopes {#allocations}&quot;">​</a></h1><p>Allocations are how Managers plan and distribute work. They are a planning tool — they do not gate who can log time.</p><hr><h2 id="what-is-an-envelope" tabindex="-1">What is an envelope? <a class="header-anchor" href="#what-is-an-envelope" aria-label="Permalink to &quot;What is an envelope? {#what-is-an-envelope}&quot;">​</a></h2><p>An <strong>envelope</strong> is a per-person hour budget on a specific project.</p><p>Think of it literally: you have a project with 200 hours in its budget. As a Manager, you put 60 hours in an envelope for Alice, 80 hours for Bob, and 60 hours for Carol. Each person&#39;s envelope is their planned share of the work.</p><ul><li><strong>Alice&#39;s envelope</strong>: 60 hours on Nike Rebrand</li><li><strong>Bob&#39;s envelope</strong>: 80 hours on Nike Rebrand</li><li><strong>Carol&#39;s envelope</strong>: 60 hours on Nike Rebrand</li></ul><p>The word &quot;allocation&quot; and the word &quot;envelope&quot; mean the same thing in VERA. The underlying data lives in the <code>07. Budgets</code> sheet (despite the name, this sheet stores per-person allocations, not project budgets).</p><hr><h2 id="allocations-vs-budgets" tabindex="-1">Allocations vs. budgets <a class="header-anchor" href="#allocations-vs-budgets" aria-label="Permalink to &quot;Allocations vs. budgets&quot;">​</a></h2><p>These two words are often confused. In VERA they mean different things:</p><table tabindex="0"><thead><tr><th>Term</th><th>What it is</th><th>Who sets it</th><th>Where it lives</th></tr></thead><tbody><tr><td><strong>Budget</strong></td><td>Total project hours — the whole pie</td><td>Owner</td><td><code>02. Projects</code>.<code>budget_hours</code></td></tr><tr><td><strong>Allocation</strong></td><td>One person&#39;s slice of that pie</td><td>Manager or Owner</td><td><code>07. Budgets</code></td></tr></tbody></table><blockquote><p><strong>Owners and Managers can have envelopes too.</strong> Any active user — regardless of role — can receive an allocation envelope. An Owner or Manager asking &quot;create an envelope for me on Project X&quot; is a completely valid request. PM assignment and allocation envelopes are separate concerns: being a PM means you manage the project; having an envelope means your hours on that project are tracked against a plan. These are independent.</p></blockquote><p>The sum of all allocations on a project should not exceed the project&#39;s total budget. VERA will warn you if it does, but it won&#39;t hard-block the creation.</p><hr><h2 id="allocations-vs-assignments" tabindex="-1">Allocations vs. assignments <a class="header-anchor" href="#allocations-vs-assignments" aria-label="Permalink to &quot;Allocations vs. assignments&quot;">​</a></h2><p>These terms are also used interchangeably in conversation, but they have a precise meaning in VERA:</p><ul><li><strong>Assignment</strong>: the state of being allocated to a project — i.e. having at least one active envelope row</li><li><strong>Allocation</strong>: the specific envelope record (with an hours amount and optional task tag)</li></ul><p>When someone asks &quot;who is on this project?&quot;, the answer is: everyone with an active allocation.</p><p>When someone asks &quot;what should I work on?&quot;, the answer is: your active allocations — the projects you have envelopes on, with hours remaining.</p><hr><h2 id="allocations-do-not-gate-time-logging" tabindex="-1">Allocations do not gate time logging <a class="header-anchor" href="#allocations-do-not-gate-time-logging" aria-label="Permalink to &quot;Allocations do not gate time logging&quot;">​</a></h2><p>This is the most important thing to understand about allocations:</p><p><strong>Anyone can log time to any active project, regardless of whether they have an allocation.</strong></p><p>Allocations are a planning and visibility tool. They answer &quot;how was the work supposed to be distributed?&quot; — they are not an access control mechanism.</p><p>If a User logs time to a project they aren&#39;t allocated to, VERA records it. If they log more hours than their envelope, VERA records it (and flags the overdraw). The system trusts that Managers are monitoring allocations and responding to alerts.</p><hr><h2 id="envelope-fields" tabindex="-1">Envelope fields <a class="header-anchor" href="#envelope-fields" aria-label="Permalink to &quot;Envelope fields&quot;">​</a></h2><p>Each allocation envelope has:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>Permanent sequential ID — use this to update or cancel</td></tr><tr><td><code>user_id</code></td><td>The person this envelope belongs to</td></tr><tr><td><code>project_id</code></td><td>The project it&#39;s for</td></tr><tr><td><code>allocated_hours</code></td><td>Hours budgeted for this person on this project</td></tr><tr><td><code>task_id</code></td><td>Optional: work category tag (links to a task type)</td></tr><tr><td><code>status</code></td><td><code>active</code> or <code>cancelled</code></td></tr><tr><td><code>created_by</code></td><td>Manager or Owner who created the envelope</td></tr><tr><td><code>created_at</code></td><td>Date created</td></tr></tbody></table><p>The optional <code>task_id</code> tag is <strong>not</strong> a constraint on what tasks the person can log — it&#39;s metadata saying &quot;this envelope is intended for Design work&quot; (or whichever task type). It helps with estimates-vs-actuals breakdowns.</p><hr><h2 id="lifetime-envelopes" tabindex="-1">Lifetime envelopes <a class="header-anchor" href="#lifetime-envelopes" aria-label="Permalink to &quot;Lifetime envelopes&quot;">​</a></h2><p>Allocations are not weekly or monthly — they are a project-lifetime budget. An envelope of 160 hours doesn&#39;t mean 160 hours this week; it means the person is allocated 160 hours in total on that project.</p><p>VERA tracks how many of those hours have been logged and how many remain.</p><hr><h2 id="budget-overdraw" tabindex="-1">Budget overdraw <a class="header-anchor" href="#budget-overdraw" aria-label="Permalink to &quot;Budget overdraw&quot;">​</a></h2><p>When a person has logged more hours than their allocated budget on a project, that is a <strong>budget overdraw</strong>.</p><p>VERA surfaces overdraws in morning and evening summaries, and via <code>get_estimates_vs_actuals</code>. A delta &gt; 0 means over-plan. Example:</p><blockquote><p>&quot;⚠️ Bob has logged 45h on Nike Rebrand but only has 40h allocated — 5h over allocation.&quot;</p></blockquote><p>Overdraw doesn&#39;t block logging. It&#39;s a signal for the Manager to either update the allocation or have a scope conversation with the client.</p><hr><h2 id="capacity-and-overbooking" tabindex="-1">Capacity and overbooking <a class="header-anchor" href="#capacity-and-overbooking" aria-label="Permalink to &quot;Capacity and overbooking&quot;">​</a></h2><p><strong>Team availability</strong> is the aggregate view: for each person, how many hours are they allocated vs. how many are free.</p><p><strong>Overbooking</strong> happens when a person&#39;s total allocations across all their projects exceed their available capacity.</p><p>VERA detects overbooking when you create or update an allocation via <code>allocate_hours</code>. If the allocation would put someone over capacity, VERA returns <code>overbooked: true</code> and flags the person and hours over. This doesn&#39;t block the allocation — it&#39;s a warning.</p><p>Use <code>get_team_availability</code> to see everyone&#39;s headroom across all projects. Use <code>check_capacity</code> when evaluating whether the team can take on new work.</p><hr><h2 id="allocation-lifecycle" tabindex="-1">Allocation lifecycle <a class="header-anchor" href="#allocation-lifecycle" aria-label="Permalink to &quot;Allocation lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>allocate_hours → active envelope</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>update_allocation → change hours (up or down)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>cancel_allocation → envelope marked cancelled (not deleted)</span></span></code></pre></div><p>Cancelled allocations are kept for audit trail purposes. When you query allocations, VERA returns only active envelopes by default.</p><hr><h2 id="common-allocation-queries" tabindex="-1">Common allocation queries <a class="header-anchor" href="#common-allocation-queries" aria-label="Permalink to &quot;Common allocation queries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Tool</th></tr></thead><tbody><tr><td>&quot;What should I work on?&quot;</td><td><code>get_my_assignments</code></td></tr><tr><td>&quot;What are Alice&#39;s allocations?&quot;</td><td><code>get_person_allocation_summary</code></td></tr><tr><td>&quot;Who is on the Nike project?&quot;</td><td><code>get_project_assignments</code></td></tr><tr><td>&quot;How much headroom does the team have?&quot;</td><td><code>get_team_availability</code></td></tr><tr><td>&quot;How did plan vs actual compare last week?&quot;</td><td><code>get_estimates_vs_actuals</code></td></tr><tr><td>&quot;Can we take on new work in April?&quot;</td><td><code>check_capacity</code></td></tr><tr><td>&quot;What&#39;s the 4-week capacity outlook?&quot;</td><td><code>get_capacity_forecast</code></td></tr></tbody></table>`,54)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
